// Block (composition) — a session in progress: a run, a focus block, a race.
// Card owns the surface, Badge the live mark, Button the controls; Stack and Grid arrange.
import { useId } from "react";
import type { Ref } from "react";
import { Badge } from "../components/Badge";
import { Button } from "../components/Button";
import { Card } from "../components/Card";
import { Grid } from "../layouts/Grid";
import { Stack } from "../layouts/Stack";
import "./ActiveSession.css";

export interface ActiveSessionMetric {
  /** What the value measures ("Distance"). */
  label: string;
  /** The value as it should read ("4.2 km"). */
  value: string;
}

export interface ActiveSessionProps {
  /** The session's name ("Morning run"). It names the section. */
  title: string;
  /** The one figure the session is about, usually the elapsed time. */
  primary: ActiveSessionMetric;
  /** Supporting figures under it; three read best. */
  metrics?: ActiveSessionMetric[];
  /** Whether the session is running now. Paused, the live mark is replaced by `pausedLabel`. */
  isPaused?: boolean;
  /** Called with the new paused state when Pause or Resume is pressed. */
  onPauseChange?: (isPaused: boolean) => void;
  /** Called when End is pressed. */
  onEnd?: () => void;
  liveLabel?: string;
  pausedLabel?: string;
  pauseLabel?: string;
  resumeLabel?: string;
  endLabel?: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function ActiveSession({
  title,
  primary,
  metrics = [],
  isPaused = false,
  onPauseChange,
  onEnd,
  liveLabel = "Live",
  pausedLabel = "Paused",
  pauseLabel = "Pause",
  resumeLabel = "Resume",
  endLabel = "End",
  className,
  ref,
}: ActiveSessionProps) {
  const titleId = useId();
  return (
    <Card className={className ? `sd-activesession ${className}` : "sd-activesession"}>
      <Stack as="section" ref={ref} aria-labelledby={titleId} gap="large" className="sd-activesession__content">
        {/* `start`, so the Badge sits on the title's first line when a long title wraps. The title and the
            status sit at the row's two ends, so the gap is spread-regions' `small` (token-contract.md
            § By relationship), a clearance under the free space between them. */}
        <Stack direction="row" justify="between" align="start" gap="small" className="sd-activesession__header">
          <>
            <h2 id={titleId} className="sd-activesession__title sd-type-title-medium">
              {title}
            </h2>
          </>
          {/* A running session is happening now (`live`); a paused one is a plain state. */}
          <Badge variant={isPaused ? "neutral" : "live"} className="sd-activesession__status">
            {isPaused ? pausedLabel : liveLabel}
          </Badge>
        </Stack>
        <>
          <Stack gap="2x-small" className="sd-activesession__primary-group">
            <span className="sd-activesession__label sd-type-label-medium">{primary.label}</span>
            <span className="sd-activesession__primary sd-type-display-medium">{primary.value}</span>
          </Stack>
        </>
        {metrics.length > 0 && (
          <>
            <Grid as="dl" columns={Math.min(metrics.length, 3)} gap="medium" className="sd-activesession__metrics">
              {metrics.map((metric) => (
                <Stack key={metric.label} gap="2x-small" className="sd-activesession__metric">
                  <dt className="sd-activesession__label sd-type-label-medium">{metric.label}</dt>
                  <dd className="sd-activesession__value sd-type-body-medium-emphasized">{metric.value}</dd>
                </Stack>
              ))}
            </Grid>
          </>
        )}
        <Stack direction="row" gap="x-small" className="sd-activesession__actions">
          <Button variant="secondary" onPress={() => onPauseChange?.(!isPaused)}>
            {isPaused ? resumeLabel : pauseLabel}
          </Button>
          {/* Ending a live session cannot be undone from here, so it is the destructive press. */}
          <Button variant="destructive" onPress={onEnd}>
            {endLabel}
          </Button>
        </Stack>
      </Stack>
    </Card>
  );
}

/* ActiveSession.css — .sd-activesession (Block)
   Arrangement only: Card owns the surface, Badge and Button their look. */
.sd-activesession__title {
  margin: 0;
}

/* The Badge is a chip beside the title: content-sized, never stretched. */
.sd-activesession__status {
  flex: none;
}

/* Figures that change in place keep their width, so they do not jitter as digits change. */
.sd-activesession__primary,
.sd-activesession__value {
  font-variant-numeric: tabular-nums;
}

.sd-activesession__metrics {
  margin: 0;
}

.sd-activesession__value {
  margin: 0;
}
